"""Summary of fixtures."""


class FixtureSummary:
    def __init__(self, fixtures):
        self._fixtures = fixtures

    def count(self):
        """Return how many fixtures there are."""
        return sum(1 for _ in self._fixtures)

    def mean_goals(self):
        """Return the mean goals, or 0.0 when there are no fixtures."""
        total = sum(x.goals for x in self._fixtures)
        n = self.count()
        return total / n if n else 0.0
